use std::fs

fn all_digits(s: string) -> bool {
    if s.len() == 0 {
        return false
    }
    for c in s.chars() {
        if c < '0' || c > '9' {
            return false
        }
    }
    true
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let mut us: Vec<string> = []
    let mut as_: Vec<string> = []
    let mut ss: Vec<int> = []
    let mut bad = 0
    for line in text.lines() {
        let parts: Vec<string> = line.split_whitespace().map(|p| p.to_string()).collect()
        if parts.len() != 3 || !all_digits(parts[2]) {
            bad += 1
            continue
        }
        us.push(parts[0])
        as_.push(parts[1])
        ss.push(parts[2].parse::<int>().unwrap_or(0))
    }
    let n: usize = us.len()
    let mut names: Vec<string> = []
    let mut tot: Vec<int> = []
    let mut cnt: Vec<int> = []
    for i in 0..n {
        let mut found = false
        let mut fi: usize = 0
        for j in 0..names.len() {
            if names[j] == us[i] {
                found = true
                fi = j
            }
        }
        if !found {
            names.push(us[i])
            tot.push(ss[i])
            cnt.push(1)
        } else {
            tot[fi] = tot[fi] + ss[i]
            cnt[fi] = cnt[fi] + 1
        }
    }
    let m: usize = names.len()
    let mut order: Vec<usize> = []
    for i in 0..m {
        order.push(i)
    }
    for i in 0..m {
        for j in 0..(m - 1 - i) {
            let a = order[j]
            let b = order[j + 1]
            let swap = tot[a] < tot[b] || (tot[a] == tot[b] && names[a] > names[b])
            if swap {
                order[j] = b
                order[j + 1] = a
            }
        }
    }
    for oi in 0..m {
        let u = order[oi]
        let mut best = ""
        let mut bc = 0
        for i in 0..n {
            if us[i] == names[u] {
                let mut c = 0
                for k in 0..n {
                    if us[k] == names[u] && as_[k] == as_[i] {
                        c += 1
                    }
                }
                if c > bc || (c == bc && as_[i] < best) {
                    bc = c
                    best = as_[i]
                }
            }
        }
        println("${names[u]} ${cnt[u]} ${tot[u]} ${best}")
    }
    println("malformed: ${bad}")
}

